-- The brief used to be regenerated on every click and thrown away, so the Intelligence page
-- could never show real entities or key points without paying for another model call.
-- Persisting the structured payload makes those fields the same ones the gate is measured on.
alter table public.documents
  add column if not exists ai_brief jsonb;

comment on column public.documents.ai_brief is
  'Structured brief (summary, key points, entities, questions) generated by the API; null until requested.';
